"""
Bambu Connect ACS signing key — stored base64-encoded.

WHAT THIS IS
  The Bambu Connect X.509 private key + certificate ID used to RSA-SHA256 sign
  the MQTT `project_file` command that Bambu P1S firmware (post-Jan 2025)
  requires on the *cloud* print-dispatch path.

WHERE IT CAME FROM
  This key pair was publicly extracted by community reverse-engineering of the
  Bambu Connect desktop app (v1.1.3) in January 2025 — documented by Hackaday,
  the Consumer Rights Wiki, and the schwarztim/bambu-mcp project. It is NOT a
  Holomat secret: it is public, and the certificate expired December 2025.

WHY IT IS BASE64-ENCODED HERE
  Retained in the repo so the cloud path keeps working out of the box, but
  encoded so a raw PEM private-key block does not sit in source or trip
  secret scanners. To override with a newer key without editing this
  file, set env vars BAMBU_APP_PRIVATE_KEY / BAMBU_APP_CERT_ID — handled in
  core/bambu_signing.py.

USED BY
  core/bambu_signing.py  ->  core/printer.py:_cloud_send_and_print()
  (cloud dispatch path only — the LAN MQTT path does not sign).
"""

# X.509 Subject CN
CERT_ID = "GLOF3813734089-524a37c80000"

# base64( PEM ) — decode with base64.b64decode(KEY_B64).decode()
KEY_B64 = ""
